from decimal import Decimal
from fractions import Fraction
from pathlib import Path
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(p):
    return Path(p).read_bytes().decode("utf-8-sig").replace("\r\n", "\n").replace("\r", "\n")


def rows_csv(p, delim=","):
    txt = read_text(p)
    return [r for r in csv.DictReader(io.StringIO(txt), delimiter=delim, quotechar='"')
            if r and any((v or "").strip() for v in r.values() if isinstance(v, str))]


def local_to_epoch(naive, tz, dst=None):
    """Instant (epoch seconds) of a local wall-clock time. dst: None/True/False to resolve repeats."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset():
        if dst is None:
            dst = True  # first occurrence
        c = a if bool(a.dst()) == dst else b
        # a (fold=0) is the first occurrence; pick the one whose dst flag matches
        if bool(a.dst()) != bool(b.dst()):
            c = a if bool(a.dst()) == dst else b
        else:
            c = a
    else:
        c = a
    return int(c.timestamp())


def std_offset(naive, tz):
    a = naive.replace(tzinfo=tz, fold=0)
    return a.utcoffset() - (a.dst() or timedelta(0))


def parse_12h(t):
    m = re.fullmatch(r"\s*(\d{1,2}):(\d{2}):(\d{2})\s*([AaPp])[Mm]\s*", t)
    h, mi, s, ap = int(m[1]), int(m[2]), int(m[3]), m[4].upper()
    h = h % 12 + (12 if ap == "P" else 0)
    return h, mi, s


def load_site(site, tzname, fmt, d):
