            continue
        if fmt == "abbr-csv":
            for r in rows_csv(f):
                r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                mo, dd, yy = map(int, r["Date"].split("/"))
                h, mi, s = parse_12h(r["Time"])
                z = r["Zone"].upper()
                dst = True if z.endswith("DT") else (False if z.endswith("ST") else None)
                ep = local_to_epoch(datetime(yy, mo, dd, h, mi, s), tz, dst)
                out.append((r["Record"], r["Badge"], r["Punch"].upper(), ep))
        elif fmt == "epoch-jsonl":
            for line in read_text(f).split("\n"):
                if not line.strip():
                    continue
                o = json.loads(line)
                if o.get("heartbeat"):
                    continue
                if "ts_ms" in o:
                    ep = int(o["ts_ms"]) // 1000
                elif "ts" in o:
                    ep = int(o["ts"])
                else:
                    continue
                out.append((str(o["id"]), o["emp"].strip(), o["dir"].upper(), ep))
        elif fmt == "offset-csv":
            for r in rows_csv(f, ";"):
                ts = datetime.fromisoformat(r["timestamp"].strip())
                dr = "IN" if r["event"].strip() == "clock_in" else "OUT"
                out.append((r["punch_id"].strip(), r["employee"].strip(), dr, int(ts.timestamp())))
