                ep = int((dt - timedelta(seconds=so.total_seconds()) - datetime(1970, 1, 1)).total_seconds())
                out.append((pid, badge, dr, ep))
        elif fmt == "de-tsv":
            for r in rows_csv(f, "\t"):
