                h, mi = map(int, r["Uhrzeit"].split(":")[:2])
                dst = True if r["Zeitzone"].upper() == "MESZ" else (False if r["Zeitzone"].upper() == "MEZ" else None)
                ep = local_to_epoch(datetime(yy, mo, dd, h, mi), tz, dst)
                out.append((r["Nr"], r["Ausweis"], "IN" if r["Buchung"].upper() == "K" else "OUT", ep))
        elif fmt == "local-csv":
            for r in rows_csv(f):
                r = {k.strip(): (v or "").strip() for k, v in r.items() if k}
                dt = datetime.strptime(r["local_time"], "%Y-%m-%d %H:%M:%S")
                out.append((r["punch_ref"], r["employee_id"], r["direction"].upper(), local_to_epoch(dt, tz, True)))
        elif fmt == "local-jsonl":
            for line in read_text(f).split("\n"):
                if not line.strip():
                    continue
                o = json.loads(line).get("punch")
                if not o:
                    continue
                dt = datetime.strptime(o["at"], "%Y-%m-%d %H:%M:%S")
