    for emp, lst in byemp.items():
        lst.sort()
        kept = []
        last = None
        for ep, _, site, pid, dr in lst:
            if last is not None and last[4] == dr and ep - last[0] <= 300:
                if inp_(day_of(rnd(ep, site), emp)):
                    exc["duplicates_dropped"] += 1
                continue
            last = (ep, 0, site, pid, dr)
            kept.append((rnd(ep, site), site, dr))
        shifts = []
        cur = None
        for rep, site, dr in kept:
            if dr == "IN":
                if cur:
                    if inp_(day_of(cur[0], emp)):
                        exc["open_shifts"] += 1
                cur = (rep, site)
            else:
                if cur and rep - cur[0] <= 16 * 3600:
                    shifts.append((cur[0], rep, cur[1]))
                    cur = None
                else:
