        daily = {}
        for r in rows:
            used = daily.get(r[1], 0)
            dot = max(0, used + r[2] - 480) - max(0, used - 480)
            daily[r[1]] = used + r[2]
            r[4] = dot
            r.append(r[2] - dot)  # non-daily-OT minutes
        weekly = {}
        for r in rows:
            wk = r[1] - timedelta(days=r[1].weekday())
            used = weekly.get(wk, 0)
            wot = max(0, used + r[5] - 2400) - max(0, used - 2400)
            weekly[wk] = used + r[5]
            r[4] += wot
