            pay = rate * (Fraction(reg) + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            e = res[emp]
            e["shifts"] += 1
            e["paid_minutes"] += paid
            e["overtime_minutes"] += ot
            e["night_minutes"] += night
            e["gross"] += pay

    def cents(fr):
        return (fr * 100 + Fraction(1, 2)).__floor__()

    def money(c):
        return "%d.%02d" % divmod(c, 100)

    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    outemps = {}
    for e, v in res.items():
        c = cents(v["gross"])
        totc += c
        for k in tot:
            tot[k] += v[k]
        outemps[e] = {k: v[k] for k in tot}
        outemps[e]["gross"] = money(c)
    tot["gross"] = money(totc)
    Path(outp).parent.mkdir(parents=True, exist_ok=True)
    Path(outp).write_text(json.dumps(dict(period=dict(start=period["start"], end=period["end"]),
                                          employees=outemps, exceptions=exc, totals=tot), indent=1))


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
